/**
 * Converts an array of string values into a CSV row string.
 * @param {string[]} values - The cells of the row.
 * @returns {string} - A CSV row without trailing newline.
 */
export function csvRow(values) {
    return values.map(escapeCsvField).join(',');
}

/**
 * Escapes a string for CSV format according to RFC 4180.
 * @param {string} value - The value to escape.
 * @returns {string} - Quoted and escaped string.
 */
function escapeCsvField(value) {
    if (typeof value !== 'string' || value.search(/[\x0d\x0a"\,\]/gi) === -1) {
        return value;
    }
    const escaped = value.replace(/\"/g, '""').replace(/\r\n?|\n/g, '\\n');
    return '"' + escaped + '"';
}"}

