    assert.equal(
        csvRow(['  spaces  ']),
        '  spaces  '
    );
    assert.equal(
        csvRow(['字符🌍']),
        '字符🌍'
    );
    assert.equal(
        csvRow(['', 'empty',' ','\t\t']),
        ',"empty", ,\\t\\t'
    );
});
